set COMB_MAX_DELAY_NS 3.0
if {[info exists ::env(COMB_MAX_DELAY_NS)] && $::env(COMB_MAX_DELAY_NS) ne ""} {
    set COMB_MAX_DELAY_NS $::env(COMB_MAX_DELAY_NS)
}
set CLK_CMD_RE {^\s*(create_clock|set_clock_latency|set_clock_uncertainty|set_clock_transition|set_input_delay|set_output_delay)(\s|$)}
set sdc_fh [open "orig.sdc" r]
set sdc_lines [split [read $sdc_fh] "\n"]
close $sdc_fh
if {[llength $sdc_lines] > 0 && [lindex $sdc_lines end] eq ""} {
    set sdc_lines [lrange $sdc_lines 0 end-1]
}
set sdc_fh [open "cleaned.sdc" w]
set in_drop 0
foreach line $sdc_lines {
    if {$in_drop} {
        if {![regexp {\\\s*$} $line]} {
            set in_drop 0
        }
        continue
    }
    if {[regexp $CLK_CMD_RE $line]} {
        set in_drop 1
        if {![regexp {\\\s*$} $line]} {
            set in_drop 0
        }
        continue
    }
    puts $sdc_fh $line
}
puts $sdc_fh "set_max_delay ${COMB_MAX_DELAY_NS} -from \[all_inputs\] -to \[all_outputs\]"
close $sdc_fh
puts "INFO: wrote cleaned.sdc"

import re, sys

CLK = ["create_clock", "set_clock_latency", "set_clock_uncertainty",
       "set_clock_transition", "set_input_delay", "set_output_delay"]

def txt(p):
    return open(p).read()

errors = []

mapped = txt("deliver/addr_to_rowcol_region_mapped.sdc")
mlines = mapped.splitlines()
for c in CLK:
    pat = re.compile(r"^\s*" + re.escape(c) + r"(\s|$)")
    for ln in mlines:
        if pat.match(ln):
            errors.append("mapped.sdc still has clock cmd %s: %r" % (c, ln))
if not re.search(r"set_max_delay\s+3\.0\s+-from\s+\[all_inputs\]\s+-to\s+\[all_outputs\]", mapped):
    errors.append("mapped.sdc missing/wrong set_max_delay")
if "set_load" not in mapped:
    errors.append("mapped.sdc missing set_load")
if "set_input_transition" not in mapped:
    errors.append("mapped.sdc missing set_input_transition")

synth = txt("deliver/synth.tcl")
for step in ["analyze", "elaborate", "link", "compile", "write"]:
    if step not in synth:
        errors.append("synth.tcl missing step: %s" % step)
for c in CLK:
    if c not in synth:
        errors.append("synth.tcl does not reference %s for stripping" % c)
if "set_max_delay" not in synth:
    errors.append("synth.tcl missing set_max_delay")
if "COMB_MAX_DELAY_NS" not in synth:
    errors.append("synth.tcl missing COMB_MAX_DELAY_NS")
if "all_outputs" not in synth:
    errors.append("synth.tcl missing all_outputs (generic)")
if "write_sdc" not in synth:
    errors.append("synth.tcl missing write_sdc step")

print("===== mapping validation =====\n")
if errors:
    for e in errors:
        print("FAIL:", e)
    sys.exit(1)
else:
    print("ALL CHECKS PASSED")
